import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String a = scanner.next();
        int indexAt = a.indexOf("at", 1);
        if (indexAt != -1) {
            a = a.substring(0, indexAt) + "@" + a.substring(indexAt + 2);
        }
        int indexDot = a.indexOf("dot", 1);
        while (indexDot != -1 && indexDot <= a.length() - 3) {
            a = a.substring(0, indexDot) + "." + a.substring(indexDot + 3);
            indexDot = a.indexOf("dot", indexDot + 1);
        }
        System.out.println(a);
    }
}
